int isMLOConnectionSupported(int ap,int sta){
 int phase=nvram_get("MLOsupportPhase")?nvram_get_int("MLOsupportPhase"):1;
 for(unsigned i=0;i<sizeof(pairs)/sizeof(*pairs);i++)if(pairs[i].ap==ap&&pairs[i].sta==sta)return pairs[i].phase>0&&pairs[i].phase<=phase;
 return 0;
}
